using System;using System.IO;using System.Linq;using System.Text;using System.Xml;using System.Xml.Linq;using System.Collections.Generic;
class NativeInstallerTests {
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static string Rel="SimObjects/Airplanes/prosim-b738-2026/";
 static void Main(string[] args){string source=args[0],root=Path.Combine(Path.GetTempPath(),"JetwayBellTests-"+Guid.NewGuid().ToString("N").Substring(0,8)),home=Path.Combine(root,"home"),community=Path.Combine(root,"Community"),aircraft=Path.Combine(community,"prosim-b738");Directory.CreateDirectory(home);Copy(Path.Combine(source,"gsx-jetway-bell"),Path.Combine(home,"gsx-jetway-bell"));string panel=Path.Combine(aircraft,Rel+"panel/panel.cfg"),sound=Path.Combine(aircraft,Rel+"sound/sound.xml");Directory.CreateDirectory(Path.GetDirectoryName(panel));Directory.CreateDirectory(Path.GetDirectoryName(sound));File.WriteAllText(panel,"[VCockpit01]\r\nhtmlgauge00=Other/Gauge.html,0,0,1,1\r\n");
 string xml="<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<!-- legacy "+(char)0x2013+" -->\r\n<SoundInfo><SimVarSounds><Sound WwiseEvent=\"custom_sound_01\" FileName=\"DoorSound\" /></SimVarSounds></SoundInfo>";File.WriteAllBytes(sound,Encoding.GetEncoding(1252).GetBytes(xml));File.WriteAllText(Path.Combine(aircraft,"layout.json"),"{\"content\":[]}");
 string data=Path.Combine(home,"UserData"),recording="Sounds/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa.wav";Directory.CreateDirectory(Path.Combine(data,"Sounds"));File.Copy(Path.Combine(source,"GSX_Jetway_Bell.wav"),Path.Combine(data,recording));string settings="<SoundSettings><Default file=\""+recording+"\"/><Airport icao=\"EDDF\" file=\""+recording+"\"/></SoundSettings>";File.WriteAllText(Path.Combine(data,"settings.xml"),settings);
 for(int cycle=0;cycle<2;cycle++){Console.WriteLine(NativeInstaller.Run(home,community,false,false));var doc=NativeInstaller.ReadXml(sound);Check(doc.SelectNodes("//Sound[starts-with(@FileName,'GSX_Jetway_Custom_EDDF_')]").Count==3,"airport definitions");foreach(XmlElement n in doc.SelectNodes("//Sound[starts-with(@FileName,'GSX_Jetway_Custom_EDDF_')]")){Check(System.Text.RegularExpressions.Regex.IsMatch(n.GetAttribute("WwiseEvent"),"^custom_(sound|misc_sound|instrument_sound|ground_sound|rattle_sound)_(0[1-9]|1[0-2])$"),"SDK-supported WAV slot required");Check(n.GetAttribute("WwiseEvent")!="custom_sound_01","existing door slot reserved");}Check(doc.OuterXml.Contains(((char)0x2013).ToString()),"legacy characters retained");Check(File.ReadAllText(Path.Combine(data,"settings.xml"))==settings,"upgrade settings preservation");}
 File.AppendAllText(panel,"\r\n[UserSection]\r\nvalue=keep");Console.WriteLine(NativeInstaller.Run(home,community,true,false));Check(!Directory.Exists(Path.Combine(community,"gsx-jetway-bell")),"package removed");Check(File.Exists(Path.Combine(data,recording)),"recording preserved");Check(File.ReadAllText(panel).Contains("value=keep")&&File.ReadAllText(panel).Contains("Other/Gauge.html")&&!File.ReadAllText(panel).Contains("GSXJetwayBell"),"targeted panel removal");Check(NativeInstaller.ReadXml(sound).SelectNodes("//Sound").Count==1,"unrelated sound retained");NativeInstaller.Run(home,community,true,false);
 NativeInstaller.Run(home,community,false,false);string originalPanel=File.ReadAllText(panel),sentinel=Path.Combine(community,"gsx-jetway-bell/unknown.txt");File.WriteAllText(sentinel,"keep");bool failed=false;try{NativeInstaller.Run(home,community,true,false);}catch{failed=true;}Check(failed&&File.Exists(sentinel)&&File.ReadAllText(panel)==originalPanel,"unknown content protected");File.Delete(sentinel);
 // In-use sound events must abort before touching aircraft/package state.
 var collision=NativeInstaller.ReadXml(sound);var node=collision.CreateElement("Sound");node.SetAttribute("WwiseEvent","custom_sound_10");node.SetAttribute("FileName","Unrelated");collision.SelectSingleNode("/SoundInfo/SimVarSounds").AppendChild(node);collision.Save(sound);byte[] originalSound=File.ReadAllBytes(sound);failed=false;try{NativeInstaller.Run(home,community,false,false);}catch{failed=true;}Check(failed&&File.ReadAllBytes(sound).SequenceEqual(originalSound)&&File.ReadAllText(panel)==originalPanel,"collision aborts without edits");
 // Force failure after aircraft mutation to exercise package/file rollback.
 collision.SelectSingleNode("//Sound[@FileName='Unrelated']").ParentNode.RemoveChild(collision.SelectSingleNode("//Sound[@FileName='Unrelated']"));collision.Save(sound);originalSound=File.ReadAllBytes(sound);string packageFile=Path.Combine(community,"gsx-jetway-bell/manifest.json");byte[] packageBytes=File.ReadAllBytes(packageFile);File.WriteAllText(Path.Combine(aircraft,"layout.json"),"{\"content\":[{\"path\":\""+Rel+"panel/panel.cfg\"},{\"path\":\""+Rel+"panel/panel.cfg\"}]}");failed=false;try{NativeInstaller.Run(home,community,false,false);}catch{failed=true;}Check(failed&&File.ReadAllBytes(sound).SequenceEqual(originalSound)&&File.ReadAllText(panel)==originalPanel&&File.ReadAllBytes(packageFile).SequenceEqual(packageBytes),"rollback restores configuration/package");
 Console.WriteLine("PASS: compiled native install, repeated upgrade, custom default/airport audio, legacy encoding, uninstall, preference preservation, collision/unknown-file protection and rollback.");
 }
 static void Copy(string source,string target){Directory.CreateDirectory(target);foreach(string f in Directory.GetFiles(source))File.Copy(f,Path.Combine(target,Path.GetFileName(f)));foreach(string d in Directory.GetDirectories(source))Copy(d,Path.Combine(target,Path.GetFileName(d)));}
}
